#pragma once

#include <cstdint>
#include <vector>

#include <image.h>

// Pattern-independent jump table detection.
//
// The fixed instruction patterns in main.cpp match the code generated by the compiler used for
// Sonic Unleashed. Later compilers (e.g. the 2010 Xbox 360 compiler, C1/C2 16.0) schedule the same
// sequences differently and pad them with `ori r0,r0,0`, so they never match. This scanner instead
// starts at every `mtctr rX; bctr` and resolves rX backwards through a small symbolic evaluator
// (lis/addis/addi/ori/or/rlwinm/add/l{b,h,w}zx), then accepts the two shapes a switch takes:
//
//   absolute:  ctr = load32(TABLE + (index << 2))
//   offset:    ctr = BASE + (load{8,16}(TABLE + index') << shift)
//
// The case count and index register come from the guarding `cmplwi crN, rI, N` + `bgt crN`.
// Every candidate is validated (labels must be aligned and inside the containing code section).
// An offset table without a guard (the compiler knew the index's range) has no known length: its
// valid entries are listed as the possible targets and the recompiler dispatches on the address.
struct DataflowSwitch
{
    uint32_t bctr{};        // address of the bctr; used as the TOML "base"
    uint32_t r{};           // index register
    uint32_t defaultLabel{};
    uint32_t table{};       // address of the table data
    uint32_t tableSize{};   // bytes
    uint32_t kind{};        // 0 absolute, 2 byte offset, 3 short offset
    bool byAddress{};       // unguarded offset table: labels are the possible targets, not indexed
    std::vector<uint32_t> labels;
};

std::vector<DataflowSwitch> ScanDataflowSwitches(const Image& image, std::vector<uint32_t>* rejected = nullptr);
